const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const repo = 'C:/Users/donabe/RemoteDesktopWorkspace/revmem-pr141-review-20261009';
const evidence = 'C:/Users/donabe/RemoteDesktopWorkspace/review-artifacts/pr141-review-20261009';
const owner = 'C:/Users/donabe/Documents/Codex/2026-10-09/task/revmem-blob-batch-review';
const expectedHead = 'a910aa2ecf5134ec900bfe3e980b5f5149169710';
const snapshot = path.join(evidence, 'validation-source');
const compiled = path.join(evidence, 'compiled');
const git = (...args) => cp.execFileSync('git', ['-C', repo, ...args], {encoding: 'utf8'}).trim();
const digest = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');
const record = (label, command, args, cwd) => {
  const startedAt = new Date().toISOString();
  const result = cp.spawnSync(command, args, {cwd, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024, timeout: 180000, windowsHide: true});
  fs.writeFileSync(path.join(evidence, label + '.stdout.log'), result.stdout || '');
  fs.writeFileSync(path.join(evidence, label + '.stderr.log'), result.stderr || '');
  const outcome = {label, command, args, cwd, sourceHead: expectedHead, startedAt, finishedAt: new Date().toISOString(), exitCode: result.status, signal: result.signal, error: result.error?.message};
  fs.writeFileSync(path.join(evidence, label + '.result.json'), JSON.stringify(outcome, null, 2));
  console.log(JSON.stringify(outcome));
  if (result.status !== 0) { console.log((result.stdout || '').slice(-4000)); console.error((result.stderr || '').slice(-4000)); }
  return result.status === 0;
};
if (git('rev-parse', 'HEAD') !== expectedHead || git('status', '--porcelain=v1') !== '') throw new Error('Reviewed source identity changed');
const lock = fs.readFileSync(path.join(repo, 'package-lock.json'));
const ownerLock = fs.readFileSync(path.join(owner, 'package-lock.json'));
if (digest(lock) !== digest(ownerLock)) throw new Error('Existing dependency lock does not match reviewed source');
const dependencies = fs.realpathSync(path.join(owner, 'node_modules'));
if (!fs.existsSync(path.join(dependencies, 'typescript', 'bin', 'tsc'))) throw new Error('TypeScript dependency unavailable');
if (fs.existsSync(snapshot)) throw new Error('Validation snapshot already exists; do not overwrite');
fs.mkdirSync(snapshot);
const manifest = [];
const contentHash = crypto.createHash('sha256');
const names = cp.execFileSync('git', ['-C', repo, 'ls-files', '-z'], {encoding: 'utf8'}).split('\0').filter(Boolean).sort();
for (const name of names) {
  const sourcePath = path.join(repo, name);
  const bytes = fs.readFileSync(sourcePath);
  const target = path.join(snapshot, name);
  fs.mkdirSync(path.dirname(target), {recursive: true});
  fs.writeFileSync(target, bytes);
  const fileHash = digest(bytes);
  manifest.push({path: name, bytes: bytes.length, sha256: fileHash});
  contentHash.update(name + '\0' + fileHash + '\n');
}
if (git('rev-parse', 'HEAD') !== expectedHead || git('status', '--porcelain=v1') !== '') throw new Error('Reviewed source changed while copying');
fs.symlinkSync(dependencies, path.join(evidence, 'node_modules'), 'junction');
const identity = {sourceHead: expectedHead, sourceTree: git('rev-parse', 'HEAD^{tree}'), sourceDirectory: repo, snapshot, compiled, dependencies, dependencyLockSha256: digest(lock), node: process.version, typescript: JSON.parse(fs.readFileSync(path.join(dependencies, 'typescript', 'package.json'))).version, git: cp.execFileSync('git', ['--version'], {encoding: 'utf8'}).trim(), platform: process.platform, sourceState: 'clean', copiedFileCount: names.length, contentManifestSha256: contentHash.digest('hex')};
fs.writeFileSync(path.join(evidence, 'validation-identity.json'), JSON.stringify(identity, null, 2));
fs.writeFileSync(path.join(evidence, 'source-manifest.json'), JSON.stringify(manifest, null, 2));
console.log(JSON.stringify(identity));
if (!record('compile-test', process.execPath, [path.join(dependencies, 'typescript', 'bin', 'tsc'), '-p', path.join(snapshot, 'tsconfig.test.json'), '--outDir', compiled], snapshot)) process.exit(1);
const tests = ['unit/cat-file-batch-parser.test.js', 'unit/node-git-blob-batch-transport.test.js', 'unit/local-git-adapter.test.js', 'unit/node-git-blob-reader.test.js', 'unit/t405-pull-request-review-runtime.test.js', 'unit/t606-r6-real-composition.test.js', 'integration/local-git-adapter.integration.test.js'];
if (!record('focused-review', process.execPath, ['--test', ...tests.map(name => path.join(compiled, 'test', name))], snapshot)) process.exitCode = 1;

