const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const {EventEmitter} = require('node:events');
const {PassThrough, Writable} = require('node:stream');
const evidence = __dirname;
const compiled = path.join(evidence, 'compiled');
const fromSource = (name) => require(path.join(compiled, 'src', name));
const {NodeGitBlobBatchTransport} = fromSource('adapters/local-git/node-git-blob-batch-transport.js');
const {GitCommandFailedError} = fromSource('adapters/local-git/contracts.js');
const {classifyOperationFailure, runWithBoundedRetry} = fromSource('application/operation-feedback/operation-feedback.js');
const {createNodeLocalGitAdapter} = fromSource('adapters/local-git/index.js');
const assert = require('node:assert/strict');

async function timeoutProbe() {
  const timers = new Map(); let nextId = 0; const signals = [];
  const child = new EventEmitter();
  child.stdin = new Writable({write(_chunk, _encoding, _done) {}});
  child.stdout = new PassThrough(); child.stderr = new PassThrough();
  child.kill = (signal) => {
    signals.push(signal);
    queueMicrotask(() => {child.stdout.end(); child.stderr.end(); child.emit('close', null, signal);});
    return true;
  };
  child.unref = () => child;
  const transport = new NodeGitBlobBatchTransport({spawnProcess: () => child,
    setTimer: callback => {const id = ++nextId; timers.set(id, callback); return id;},
    clearTimer: id => timers.delete(id)});
  let callbacks = 0;
  const observed = transport.readBlobs('/fixture', ['a'.repeat(40), 'b'.repeat(40)], () => {callbacks++;}).then(() => undefined, error => error);
  const timer = timers.entries().next().value;
  assert.ok(timer, 'manual request timer installed');
  timers.delete(timer[0]); timer[1]();
  const batchError = await observed;
  assert.ok(batchError, 'actual transport rejected its expired request');
  const singleError = new GitCommandFailedError({cwd: '/fixture', argumentsList: ['cat-file', 'blob', 'a'.repeat(40)]}, {exitCode: -1, stdout: '', stderr: 'timeout'});
  const rows = [];
  for (const [label, error] of [['actual-batch-timeout', batchError], ['existing-single-timeout-contract', singleError]]) {
    let attempts = 0; let result;
    try {result = (await runWithBoundedRetry(async () => {attempts++; if (attempts === 1) throw error; return 'recovered';}, {maxAttempts: 3, sleep: async () => {}})).value;}
    catch {result = 'rejected';}
    rows.push({label, errorName: error.name, message: error.message, classification: classifyOperationFailure(error), attempts, result});
  }
  const result = {kind: 'timeout-retry-probe', rows, callbacks, signals, pendingTimers: timers.size};
  console.log(JSON.stringify(result));
  assert.equal(rows[0].classification.kind, 'permanent');
  assert.equal(rows[0].attempts, 1);
  assert.equal(rows[1].classification.kind, 'retryable');
  assert.equal(rows[1].attempts, 2);
  assert.equal(callbacks, 0);
  assert.equal(timers.size, 0);
  return result;
}

async function parentChildProbe() {
  const fixture = path.join(evidence, 'parent-child-git-fixture');
  if (fs.existsSync(fixture)) throw new Error('Fixture already exists; refusing to overwrite');
  fs.mkdirSync(path.join(fixture, 'nested'), {recursive: true});
  fs.writeFileSync(path.join(fixture, 'nested', 'tracked.txt'), 'tracked\n');
  fs.writeFileSync(path.join(fixture, 'nested', 'other.txt'), 'other\n');
  const git = (...args) => cp.execFileSync('git', ['-C', fixture, ...args], {encoding: 'utf8'});
  git('init', '--initial-branch=main'); git('add', '--', 'nested');
  git('-c', 'user.name=Review fixture', '-c', 'user.email=review-fixture@example.invalid', 'commit', '-m', 'Synthetic parent child fixture');
  const revision = git('rev-parse', 'HEAD').trim();
  const raw = git('ls-tree', '--full-tree', '-z', revision, '--', ':(literal)nested', ':(literal)nested/tracked.txt');
  const adapter = createNodeLocalGitAdapter();
  const singleParent = await adapter.readTextFileAtRevision(fixture, revision, 'nested', 'posix');
  const singleChild = await adapter.readTextFileAtRevision(fixture, revision, 'nested/tracked.txt', 'posix');
  let batch;
  try {batch = {kind: 'returned', results: [...await adapter.readTextFilesAtRevision(fixture, revision, ['nested', 'nested/tracked.txt'], 'posix')]};}
  catch (error) {batch = {kind: 'rejected', name: error.name, message: error.message};}
  const result = {kind: 'parent-child-path-probe', git: cp.execFileSync('git', ['--version'], {encoding: 'utf8'}).trim(), revision, lsTreeRecords: raw.split('\0').filter(Boolean), singleParent, singleChild, batch};
  console.log(JSON.stringify(result));
  return result;
}

(async () => {
  const identity = JSON.parse(fs.readFileSync(path.join(evidence, 'validation-identity.json'), 'utf8'));
  const results = [await timeoutProbe(), await parentChildProbe()];
  const preload = path.join(evidence, 'scheduler-pause-probe.cjs');
  fs.writeFileSync(preload, "const originalSetTimeout=globalThis.setTimeout;let paused=false;globalThis.setTimeout=(callback,delay,...args)=>originalSetTimeout(()=>{if(!paused&&delay>0&&delay<=5){paused=true;console.error('Review probe: one synthetic 1100 ms scheduler pause before the timer callback');Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,1100);}callback(...args);},delay);\n");
  const test = path.join(compiled, 'test', 'unit', 'node-git-blob-batch-transport.test.js');
  for (const [label, extra] of [['timing-control', []], ['timing-scheduler-pause', ['--require', preload]]]) {
    const args = [...extra, '--test', '--test-name-pattern=^transport test harness fails finitely when a wait condition never occurs$', test];
    const startedAt = new Date().toISOString();
    const run = cp.spawnSync(process.execPath, args, {cwd: identity.snapshot, encoding: 'utf8', maxBuffer: 8 * 1024 * 1024, timeout: 30000, windowsHide: true});
    fs.writeFileSync(path.join(evidence, label + '.stdout.log'), run.stdout || '');
    fs.writeFileSync(path.join(evidence, label + '.stderr.log'), run.stderr || '');
    const result = {kind: label, command: process.execPath, args, sourceHead: identity.sourceHead, startedAt, finishedAt: new Date().toISOString(), exitCode: run.status, signal: run.signal, error: run.error?.message, summary: (run.stdout || '').split(/\r?\n/).filter(line => /^(# (tests|suites|pass|fail|cancelled|skipped)|not ok|  error:)/.test(line)), stderr: run.stderr};
    fs.writeFileSync(path.join(evidence, label + '.result.json'), JSON.stringify(result, null, 2));
    console.log(JSON.stringify(result));
    results.push(result);
  }
  fs.writeFileSync(path.join(evidence, 'review-probes.result.json'), JSON.stringify({sourceHead: identity.sourceHead, sourceManifest: identity.contentManifestSha256, results}, null, 2));
})().catch(error => {console.error(error); process.exitCode = 1;});
